```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

/// Maximum attempts to get the notifier to accept the digest.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once; this is the report's timestamp.
        let now = wall_clock::now();

        // One permitted fetch. A transport failure is a value, not a trap,
        // so a dead feed yields fetched == 0 rather than failing the run.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {} fetched {} chars", now.seconds, fetched);

        // `notified` may only be reported true if the notifier actually accepted.
        let mut accepted = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                accepted = true;
                break;
            }
        }

        // If the notifier never accepts, trap rather than emit a report whose
        // `notified` field would be false and violate the ensures clause.
        if !accepted {
            panic!("notifier did not accept digest; no report emitted");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

